<script setup>
import {computed,onMounted,ref} from 'vue'
import {workspaceApi as api} from '../api/workspace.js'
const props=defineProps({role:String,merchantId:Number}),rows=ref([]),merchants=ref([]),edit=ref(null),busy=ref(false),error=ref(''),success=ref('')
const admin=computed(()=>props.role==='ADMIN'),names={PUBLISHED:'已上架',DRAFT:'草稿',OFF_SHELF:'已下架'}
async function load(){busy.value=true;error.value='';try{rows.value=await api.products(props.role);if(admin.value)merchants.value=[...new Map(rows.value.map(p=>[p.merchantId,{id:p.merchantId,name:p.merchantName}])).values()]}catch(e){error.value=e.message}finally{busy.value=false}}
function open(item){success.value='';error.value='';edit.value=item?{...item}:{merchantId:props.merchantId||merchants.value[0]?.id,sku:'',name:'',description:'',category:'日常好物',pointsPrice:100,stock:0,status:'DRAFT'}}
async function save(){busy.value=true;error.value='';const e=edit.value;const body={merchantId:Number(e.merchantId),sku:e.sku,name:e.name,description:e.description,category:e.category,pointsPrice:Number(e.pointsPrice),stock:Number(e.stock),status:e.status,revision:e.revision??null};try{await api.saveProduct(props.role,e.id,body);edit.value=null;success.value='商品已保存';await load()}catch(ex){error.value=ex.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><article class="card"><div class="section-heading"><h2>{{admin?'平台商品运营':'本店商品管理'}}</h2><button class="button primary" :disabled="busy" @click="open(null)">新增商品</button></div><p v-if="success" class="notice success">{{success}}</p><p v-if="error&&!edit" class="notice error" role="alert">{{error}}</p><div class="table-scroll"><table><thead><tr><th>商品</th><th>商户</th><th>积分价格</th><th>可用库存</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="p in rows" :key="p.id"><td>{{p.name}}<small class="table-subtitle">{{p.sku}}</small></td><td>{{p.merchantName}}</td><td>{{p.pointsPrice}}</td><td>{{p.stock}}</td><td>{{names[p.status]}}</td><td><button class="button secondary" :disabled="busy" @click="open(p)">编辑</button></td></tr></tbody></table></div><p v-if="!rows.length" class="empty-state">暂无商品</p></article><div v-if="edit" class="modal-backdrop"><form class="modal scroll-modal" @submit.prevent="save"><h2>{{edit.id?'编辑商品':'新增商品'}}</h2><p v-if="error" class="notice error" role="alert">{{error}}</p><label>商户<select v-if="admin" v-model="edit.merchantId" :disabled="!!edit.id" required><option v-for="m in merchants" :key="m.id" :value="m.id">{{m.name}}</option></select><input v-else :value="'#'+edit.merchantId" disabled/></label><label>SKU<input v-model="edit.sku" :disabled="!!edit.id" pattern="[A-Z0-9_-]{3,40}" required maxlength="40"/></label><label>商品名称<input v-model="edit.name" required maxlength="100"/></label><label>描述<textarea v-model="edit.description" required maxlength="500"/></label><label>分类<input v-model="edit.category" required maxlength="30"/></label><div class="form-columns"><label>积分价格<input v-model.number="edit.pointsPrice" type="number" min="1" max="10000000" required/></label><label>当前可用库存<input v-model.number="edit.stock" type="number" min="0" max="1000000" required/></label></div><label>状态<select v-model="edit.status"><option value="DRAFT">草稿</option><option value="PUBLISHED">上架</option><option value="OFF_SHELF">下架</option></select></label><div class="action-row"><button class="button primary" :disabled="busy">保存商品</button><button type="button" class="button secondary" :disabled="busy" @click="edit=null">关闭</button></div></form></div></template>
